refentry.refsect1:
&reftitle.parameters;
socket
A Socket instance created with socket_create, socket_accept or socket_create_pair.

  &reftitle.examples;

   socket_export_stream example


<?php
socket_create_pair(AF_UNIX, SOCK_STREAM, 0, $pair);

$stream = socket_export_stream($pair[0]);
var_dump(socket_export_stream($pair[0]) === $stream);

fwrite($stream, 'Hello');
echo socket_read($pair[1], 5), PHP_EOL;


   &example.outputs;


bool(true)
Hello
